/* sys.c - every syscall stub linked (allsys.c, generated by tests/run.py from hzsys.h),
 * the safe ones called, the parameter blocks' sizes. Prints SYS PASS or SYS FAIL. */
#include <stdio.h>
#include <string.h>
#include <horizon.h>

extern void (*hz_all_syscalls[])(void);
extern unsigned hz_all_count;

static unsigned checks, fails, called;

static void check(int ok, const char *what)
{
    ++checks;
    if (!ok) {
        ++fails;
        printf("FAIL: %s (hz_errno $%02X)\n", what, hz_errno);
    }
}
#define CALLED(ok, what) (++called, check((ok), (what)))

int main(void)
{
    char buf[130];
    unsigned u, i, bank, port, pid;
    long l;
    int h;
    hz_io io;
    hz_msg msg;
    hz_taskinfo ti;
    hz_fileinfo st;
    hz_readdirblk rd;
    hz_renameblk rn;

    /* the blocks: the compiler already checked these (HZ_STATIC_ASSERT); printed for
     * the record */
    printf("sizes: io %u stat %u winopen %u windraw %u event %u sample %u sprite %u "
           "fsenter %u fsscroll %u drawrec %u sheetrec %u taskinfo %u\n",
           (unsigned)sizeof(hz_io), (unsigned)sizeof(hz_fileinfo), (unsigned)sizeof(hz_winopen),
           (unsigned)sizeof(hz_windraw), (unsigned)sizeof(hz_event), (unsigned)sizeof(hz_sample),
           (unsigned)sizeof(hz_sprite), (unsigned)sizeof(hz_fsenter), (unsigned)sizeof(hz_fsscroll),
           (unsigned)sizeof(hz_drawrec), (unsigned)sizeof(hz_sheetrec), (unsigned)sizeof(hz_taskinfo));
    check(sizeof(hz_io) == 6 && sizeof(hz_fileinfo) == 9 && sizeof(hz_winopen) == 12
          && sizeof(hz_windraw) == 17 && sizeof(hz_event) == 8 && sizeof(hz_sample) == 16
          && sizeof(hz_sprite) == 10 && sizeof(hz_fsenter) == 10 && sizeof(hz_fsscroll) == 14
          && sizeof(hz_drawrec) == 20 && sizeof(hz_sheetrec) == 16 && sizeof(hz_taskinfo) == 16
          && sizeof(hz_sheetnew) == 10 && sizeof(hz_raster) == 6 && sizeof(hz_sprmove) == 6
          && sizeof(hz_popup) == 8 && sizeof(hz_mouse) == 10 && sizeof(hz_rect) == 8,
          "block sizes");
    for (i = 0; i < hz_all_count; i++)
        if (!hz_all_syscalls[i])
            break;
    check(i == hz_all_count, "every stub linked");
    printf("stubs linked: %u (syscalls in ABI.md: %u)\n", hz_all_count, HZ_NSYSCALLS);

    pid = hz_getpid();
    CALLED(pid > 0 && pid < 63 && hz_errno == 0, "getpid");
    l = hz_uptime();
    CALLED(l > 1000, "uptime");
    hz_yield(); ++called;
    hz_sleep(20); ++called;
    hz_putc('#'); ++called;
    CALLED(hz_puts("<puts>\n") == 0, "puts");
    u = hz_con_size();
    CALLED(u == 78 && hz_x == 29, "con_size 78 x 29");
    CALLED(hz_getcwd(buf, sizeof(buf)) > 0 && buf[0] == '/', "getcwd");
    CALLED(hz_chdir("/SYSTEM") == 0, "chdir");
    hz_getcwd(buf, sizeof(buf));
    check(!strcmp(buf, "/SYSTEM"), "getcwd after chdir");
    CALLED(hz_chdir("/NOSUCHDIR") == -1 && hz_errno >= HZ_EIO, "chdir to a missing folder");
    hz_chdir("/");
    l = hz_time_get();
    CALLED(hz_errno == 0 && hz_y <= CLK_SET, "time_get");
    u = hz_mem_info();
    CALLED(u > 0 && hz_x >= u, "mem_info");
    bank = hz_bank_alloc();
    CALLED(hz_errno == 0 && bank > 0, "bank_alloc");
    CALLED(hz_bank_free(bank) == 0, "bank_free");
    CALLED(hz_bank_free(bank) == -1 && hz_errno == HZ_EINVAL, "bank_free twice: EINVAL");

    CALLED(hz_mkdir("/SYSTEST") == 0, "mkdir");
    h = hz_open("/SYSTEST/A.BIN", HZ_O_CREATE);
    CALLED(h >= 0 && h < 4, "open create");
    io.handle = (unsigned char)h;
    HZ_U24(io.buf, "0123456789");
    io.len = 10;
    CALLED(hz_write(&io) == 10, "write");
    CALLED(hz_seek(h, 4) == 4, "seek");
    io.len = 3;
    HZ_U24(io.buf, buf);
    CALLED(hz_read(&io) == 3 && !memcmp(buf, "456", 3), "read after seek");
    CALLED(hz_close(h) == 0, "close");
    CALLED(hz_close(h) == -1, "close twice fails");
    CALLED(hz_stat_path("/SYSTEST/A.BIN", &st) == 0 && st.size == 10 && !(st.attr & HZ_ATTR_DIR),
           "stat");
    HZ_U24(rn.from, "/SYSTEST/A.BIN");
    HZ_U24(rn.to, "/SYSTEST/B.BIN");
    CALLED(hz_rename(&rn) == 0, "rename");
    HZ_U24(rd.path, "/SYSTEST");
    HZ_U24(rd.buf, buf);
    rd.len = sizeof(buf);
    rd.skip = 0;
    CALLED(hz_readdir(&rd) == 1 && ((hz_dirent *)buf)->namelen == 5
           && !memcmp(buf + sizeof(hz_dirent), "B.BIN", 5), "readdir");
    CALLED(hz_delete("/SYSTEST/B.BIN") == 0, "delete");
    CALLED(hz_delete("/SYSTEST") == 0, "delete a folder");
    CALLED(hz_open("/SYSTEST/B.BIN", HZ_O_READ) == -1 && hz_errno == HZ_ENOPATH, "open: no path");

    for (u = 0, i = 0; i < 16; i++) {
        if (hz_task_info(i, &ti) == 0 && ti.id == pid)
            u = 1;
        if (ti.id)
            printf("task slot %u: id %u state %u name %.8s\n", i, ti.id, ti.state, ti.name);
    }
    called += 16;
    check(u, "task_info finds this task");
    CALLED(hz_task_name_get(0, buf) == 0 && buf[0] == 'S', "task_name_get");
    port = hz_port_create();
    CALLED(hz_errno == 0 && port < 16, "port_create");
    memset(&msg, 0, sizeof(msg));
    msg.b[0] = 42;
    CALLED(hz_send(port, &msg) == 0, "send");
    memset(&msg, 0, sizeof(msg));
    CALLED(hz_recv(port | RV_POLL, &msg) == 0 && msg.b[0] == 42, "recv");
    CALLED(hz_recv(port | RV_POLL, &msg) == -1 && hz_errno == HZ_EAGAIN, "recv poll: EAGAIN");
    CALLED(hz_port_close(port) == 0, "port_close");
    for (i = 0; i < 40; i++) {          /* the shell's Enter may still be queued */
        hz_input_poll();
        if (hz_errno)
            break;
    }
    CALLED(hz_errno == HZ_EAGAIN, "input_poll: EAGAIN once nothing is queued");
    hz_joystick();
    CALLED(hz_errno == 0, "joystick");
    u = hz_setting(1, 0xFFFF);
    CALLED(hz_errno == 0 && u <= 15, "setting (read)");
    u = hz_ws_config(0);
    CALLED(hz_errno == 0 && hz_x >= 7, "ws_config -> the hardware revision");
    printf("hardware revision $%02X\n", hz_x);
    u = hz_frame();
    CALLED(hz_errno == 0, "frame");
    hz_vsync();
    CALLED(hz_errno == 0, "vsync");
    hz_sample_stat();
    CALLED(hz_errno == 0, "sample_stat");
    CALLED(hz_list_wait(1) == 0, "list_wait (ask)");
    CALLED(hz_syscall(SYS_GETPID, 0, 0, 0) == pid && hz_errno == 0, "hz_syscall getpid");
    hz_syscall(0xFE, 0, 0, 0);
    CALLED(hz_errno == HZ_ENOSYS, "hz_syscall of an unknown number: ENOSYS");
    CALLED(hz_win_close(15) == -1 && hz_errno == HZ_EINVAL, "win_close of no window: EINVAL");
    CALLED(hz_sample_stop(0xFFFF) == 0 || hz_errno == HZ_EINVAL, "sample_stop");

    printf("syscalls called: %u\n", called);
    printf("sys: %u checks, %u failures\n", checks, fails);
    printf(fails ? "SYS FAIL\n" : "SYS PASS\n");
    return fails ? 1 : 0;
}
